const F = [
  ['NF Title', '400', 'normal', ''],
  ['NF Text', '400', 'normal', ''],
  ['NF Text', '500', 'normal', ''],
  ['NF Text', '700', 'normal', ''],
  ['NF Num', '400', 'normal', ''],
];
let done = null;
export function loadFonts() {
  if (done) return done;
  if (typeof FontFace === 'undefined' || !document.fonts) return (done = Promise.resolve());
  return (done = Promise.all(F.map(([family, weight, style, b64]) => {
    const bin = atob(b64), u = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i);
    const f = new FontFace(family, u.buffer, { weight, style, display: 'swap' }); document.fonts.add(f); return f.load().catch(() => {});
  })));
}
